<script setup lang="ts">
import {ref,onMounted} from 'vue';import {get} from '../../../../packages/shared/src/client';import {useOperations} from '../../../../packages/shared/src/operations';import {useTask,query,type Row} from '../../../../packages/shared/src/ui';import Status from '../../../../packages/shared/src/Status.vue';
const task=useTask(),ops=useOperations(),courseId=ref(''),studentId=ref(''),examPage=ref(1),stats=ref<Row>({}),learning=ref<Row>({}),courses=ref<Row[]>([]),studentPage=ref(1),questions=ref<Row[]>([]),questionTotal=ref(0),questionPage=ref(1),current=ref<Row>(),replies=ref<Row[]>([]),reply=ref(''),replyPage=ref(1),replyTotal=ref(0);
async function load(){if(!courseId.value)return;await task.run(async()=>{const [a,b,c]=await Promise.all([get<Row>('/teacher/learning-hub?'+query({courseId:courseId.value,userId:studentId.value,pageNo:studentPage.value,pageSize:20})),get<Row>('/teacher/exam-statistics?'+query({courseId:courseId.value,studentId:studentId.value,pageNo:examPage.value,pageSize:20})),get<Row>('/learning-hub/teaching/questions?'+query({courseId:courseId.value,pageNo:questionPage.value,pageSize:20}))]);learning.value=a;stats.value=b;questions.value=c.list||[];questionTotal.value=Number(c.total||0);});}
async function answers(row:Row){if(current.value?.id!==row.id)replyPage.value=1;current.value=row;await task.run(async()=>{const r=await get<Row>('/services/learning/replies/page?questionId='+row.id+'&pageNo='+replyPage.value+'&pageSize=20');replies.value=r.list||[];replyTotal.value=Number(r.total||0);});}
async function respond(){const ok=await task.run(async()=>{const op=await ops.begin('learning','教师答疑','/services/learning/replies',{questionId:current.value!.id,content:reply.value,anonymity:false});return op.status==='SUCCEEDED';});if(ok&&current.value){reply.value='';await answers(current.value);}}
async function accept(row:Row){const ok=await task.run(async()=>{const op=await ops.begin('learning','采纳学生回答','/learning-hub/questions/'+current.value!.id+'/accept',{replyId:row.id});return op.status==='SUCCEEDED';});if(ok){await load();current.value=questions.value.find(q=>q.id===current.value?.id);task.message.value='回答已采纳，积分按规则到账';}}
onMounted(async()=>{await task.run(async()=>{let page=1;const all:Row[]=[];let data:Row;do{data=await get<Row>('/teacher/courses?pageNo='+page+'&pageSize=100');all.push(...(data.list||[]));page++;}while(all.length<Number(data.total||0)&&data.list?.length);courses.value=all;courseId.value=String(all[0]?.id||'');});if(courseId.value)await load();});
</script><template><section class="card teaching-page"><h1>教学学情与答疑</h1><p>按课程查看考试表现，及时回应学生的问题。</p><Status :busy="task.busy.value" :error="task.error.value" :message="task.message.value"/><div class="toolbar"><el-select v-model="courseId" filterable aria-label="教学课程" placeholder="选择所授课程" @change="studentPage=1;questionPage=1;load()"><el-option v-for="course in courses" :key="course.id" :value="String(course.id)" :label="course.name"/></el-select><el-input v-model="studentId" aria-label="筛选学生编号" placeholder="学生编号（可选）"/><el-button type="primary" @click="questionPage=1;load()" :disabled="!courseId.trim()||task.busy.value">查看课程学情</el-button></div><p class="muted">授课范围与试卷评分范围分别验证；无权限的课程不能查看。</p><section v-if="learning.summary"><h2>{{learning.courseName}}</h2><div class="teacher-summary"><p>学习人数<strong>{{learning.summary.students}}</strong></p><p>已完成课程<strong>{{learning.summary.completedStudents}}</strong></p><p>课程完成率<strong>{{learning.summary.completionRate}}%</strong></p><p>待回答问题<strong>{{learning.summary.unansweredQuestions}}</strong></p></div><el-table :data="learning.list||[]" empty-text="暂无学习记录"><el-table-column prop="name" label="学生"/><el-table-column label="学习进度"><template #default="{row}">{{row.learnedSections}} / {{row.sections}} 小节<el-progress :percentage="Number(row.progressPercent||0)"/></template></el-table-column><el-table-column prop="latestLearnTime" label="最近学习" min-width="180"/></el-table><el-pagination v-if="learning.total>20" v-model:current-page="studentPage" :total="Number(learning.total)" :page-size="20" layout="prev,pager,next" @current-change="load"/></section><template v-if="courseId&&Number(stats.total||0)>0"><h2>考试表现</h2><el-table :data="stats.list||[]" empty-text="当前评分范围暂无记录"><el-table-column prop="course_id" label="课程编号"/><el-table-column prop="student_id" label="学生编号"/><el-table-column prop="finished" label="已评分"/><el-table-column prop="passed" label="已通过"/><el-table-column prop="pending_grading" label="待评分"/></el-table><el-pagination v-if="stats.total>20" v-model:current-page="examPage" :total="Number(stats.total)" :page-size="20" layout="prev,pager,next" @current-change="load"/></template><div class="section-heading"><h2>课程答疑</h2><RouterLink to="/exams">前往评分 →</RouterLink></div><article v-for="row in questions" :key="row.id" class="review-row"><div><h3>{{row.title}}</h3><p>{{row.answerTimes||0}} 个回答 · {{row.acceptedReplyId?'已采纳':'待处理'}}</p></div><el-button @click="answers(row)">查看与答疑</el-button></article><el-empty v-if="!questions.length&&!task.busy.value" :description="courseId?'本课程暂无待查看问题':'先选择一门所授课程'"/><el-pagination v-if="questionTotal>20" v-model:current-page="questionPage" :total="questionTotal" :page-size="20" layout="prev,pager,next" @current-change="load"/><el-dialog :model-value="!!current" title="课程答疑" @update:model-value="(v:boolean)=>{if(!v)current=undefined;}"><template v-if="current"><h3>{{current.title}}</h3><article v-for="item in replies" :key="item.id" class="review-row"><p>{{item.content}}</p><el-button v-if="!current.acceptedReplyId" @click="accept(item)" :disabled="task.busy.value">采纳回答</el-button><span v-else-if="String(current.acceptedReplyId)===String(item.id)">已采纳</span></article><el-pagination v-if="replyTotal>20" v-model:current-page="replyPage" :total="replyTotal" :page-size="20" layout="prev,pager,next" @current-change="answers(current!)"/><el-input v-model="reply" type="textarea" :rows="5" placeholder="写下教师解答"/><el-button type="primary" @click="respond" :disabled="!reply.trim()||task.busy.value">发布解答</el-button></template><Status :busy="task.busy.value" :error="task.error.value"/></el-dialog></section></template>